# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::Admission do
  # The fence stays in place until a later admission
  # Only a positive integer can match an Ownership-Generation header, so any other value must not
  # be stored: admit!(generation: nil) would otherwise fence without anyone asking for it.
  it "admit with nil, zero, negative or non-integer input keeps the fence and stores no generation" do
    described_class.ensure_initial!
    described_class.fence!(lock_timeout: 1)

    [nil, 0, -1, "4", 4.0].each do |generation|
      expect { described_class.admit!(generation:) }.to raise_error(ArgumentError)
      expect(described_class.current.generation).to be_nil
    end

    described_class.admit!(generation: 4)
    [nil, 0].each do |generation|
      expect { described_class.admit!(generation:) }.to raise_error(ArgumentError)
      expect(described_class.current.generation).to eq(4)
    end
    expect(described_class.count).to eq(1)
  end
end
